    ID() int64
    Describe() string
}
type base struct { id int64; version int }
func (b *base) ID() int64 { return b.id }
func (b *base) Touch()    { b.version++ }

type User struct { base; Email string }      // promoted ID/Touch satisfy the layer
func (u *User) Describe() string { return "user " + u.Email }
